import styled from '@emotion/styled';
import { theme } from 'theme';

interface StyledChartLegendContainerProps {
  $orientation?: 'vertical' | 'horizontal';
}

export const StyledChartLegendContainer = styled('div', {
  shouldForwardProp: (propName) => propName !== '$orientation',
})<StyledChartLegendContainerProps>(({ $orientation }) => ({
  display: 'flex',
  flexDirection: 'row',
  gap: 12,
  ...($orientation === 'vertical' && {
    flexDirection: 'column',
    alignItems: 'start',
  }),
  ...($orientation === 'horizontal' && {
    flexDirection: 'row',
    alignItems: 'center',
  }),
}));

interface StyledChartLegendItemProps {
  $clickeable?: boolean;
}

export const StyledChartLegendItem = styled('div', {
  shouldForwardProp: (propName) => propName !== '$clickeable',
})<StyledChartLegendItemProps>(({ $clickeable }) => ({
  display: 'flex',
  alignItems: 'center',
  gap: 4,
  justifyContent: 'center',
  ...($clickeable && {
    cursor: 'pointer',
  }),
}));

type LegendLabelSize = 'small' | 'medium' | 'large';
type LegendFontWeight = 'normal' | 'medium' | 'semibold' | 'bold';

interface StyledChartLegendLabelProps {
  $size?: LegendLabelSize;
  $strike?: boolean;
  $fontWeight?: LegendFontWeight;
}

const labelSizeStyles: Record<LegendLabelSize, object> = {
  small: { fontSize: '10px', lineHeight: '10px' },
  medium: { fontSize: '12px', lineHeight: '12px' },
  large: { fontSize: '14px', lineHeight: '14px' },
};

const labelFontWeightStyles: Record<LegendFontWeight, object> = {
  normal: { fontWeight: 400 },
  medium: { fontWeight: 500 },
  semibold: { fontWeight: 600 },
  bold: { fontWeight: 700 },
};

export const StyledChartLegendLabel = styled('span', {
  shouldForwardProp: (propName) =>
    !['$size', '$strike', '$fontWeight'].includes(propName),
})<StyledChartLegendLabelProps>(({ $size, $strike, $fontWeight }) => ({
  fontSize: '12px',
  lineHeight: '12px',
  fontFamily: theme.fonts.paragraph,
  color: '#141414',
  textDecoration: 'none',
  margin: 0,
  ...($size != null && labelSizeStyles[$size]),
  ...($strike && { textDecoration: 'line-through' }),
  ...($fontWeight != null && labelFontWeightStyles[$fontWeight]),
}));

type LegendShapeType = 'rectangle' | 'circle' | 'square' | 'thinPill' | 'pill';

interface StyledChartLegendShapeProps {
  $type?: LegendShapeType;
}

const shapeTypeStyles: Record<LegendShapeType, object> = {
  rectangle: {
    width: '16px',
    height: '8px',
    '&.large': { width: '24px', height: '12px' },
    '&.small': { width: '12px', height: '6px' },
  },
  circle: {
    width: '8px',
    height: '8px',
    borderRadius: '50%',
    '&.large': { width: '12px', height: '12px' },
    '&.small': { width: '4px', height: '4px' },
  },
  square: {
    width: '10px',
    height: '10px',
    '&.large': { width: '12px', height: '12px' },
    '&.small': { width: '8px', height: '8px' },
  },
  thinPill: {
    width: '12px',
    height: '4px',
    borderRadius: '999px',
    '&.large': { width: '16px', height: '4px' },
    '&.small': { width: '8px', height: '4px' },
  },
  pill: {
    width: '16px',
    height: '8px',
    borderRadius: '999px',
    '&.large': { width: '24px', height: '16px' },
    '&.small': { width: '12px', height: '8px' },
  },
};

export const StyledChartLegendShape = styled('div', {
  shouldForwardProp: (propName) => propName !== '$type',
})<StyledChartLegendShapeProps>(({ $type }) => ({
  display: 'grid',
  placeItems: 'center',
  width: '12px',
  height: '12px',
  borderRadius: '2px',
  ...($type != null && shapeTypeStyles[$type]),
}));

export const StyledChartLegendLayer = styled.div({
  width: '6px',
  height: '6px',
  borderRadius: '50%',
  '&.large': { width: '8px', height: '8px' },
  '&.small': { width: '4px', height: '4px' },
});
